// BRANCO — Painel (Cloudflare Worker + banco D1)
// Admin: vê o próprio site e gerencia clientes. Cliente: vê só o projeto dele.
// Login: Google, Facebook ou senha de admin (reserva).
//
// Variáveis na Cloudflare (Settings → Variables and Secrets):
//   ADMIN_SENHA       senha de reserva do admin (já existe)
//   ADMIN_EMAIL       seu e-mail (ex: brancowebs@gmail.com) — entra como admin pelo Google/Facebook
//   GOOGLE_ID, GOOGLE_SEGREDO       credenciais do Google
//   FACEBOOK_ID, FACEBOOK_SEGREDO   credenciais do Facebook

const SITE = 'https://produtoinf.github.io';
const TIPOS = ['visita', 'whatsapp', 'form_aberto', 'form_enviado'];
const DIA = 86400;

/* ---------- utilidades ---------- */
const json = (d, s = 200, h = {}) =>
  new Response(JSON.stringify(d), { status: s, headers: { 'Content-Type': 'application/json; charset=utf-8', ...h } });
const corta = (v, n) => (typeof v === 'string' ? v.trim().slice(0, n) : null) || null;
const urlOk = v => { const u = corta(v, 500); return u && /^https?:\/\//i.test(u) ? u : null; };
const emailOk = v => { const e = corta(v, 200); return e && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e) ? e.toLowerCase() : null; };
const slugify = s => (s || 'cliente').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30) || 'cliente';
const cookies = req => Object.fromEntries((req.headers.get('Cookie') || '').split(/;\s*/).filter(Boolean).map(c => { const i = c.indexOf('='); return [c.slice(0, i), decodeURIComponent(c.slice(i + 1))]; }));
const cookie = (k, v, max) => `${k}=${encodeURIComponent(v)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${max}`;
const b64u = buf => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const rnd = () => b64u(crypto.getRandomValues(new Uint8Array(18)));
const redir = (to, extra = []) => { const h = new Headers({ Location: to }); extra.forEach(c => h.append('Set-Cookie', c)); return new Response(null, { status: 302, headers: h }); };

/* ---------- sessão assinada (cookie) ---------- */
async function chave(env) {
  return crypto.subtle.importKey('raw', new TextEncoder().encode('branco:' + (env.ADMIN_SENHA || '')), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign', 'verify']);
}
async function assina(env, dados) {
  const corpo = b64u(new TextEncoder().encode(JSON.stringify({ ...dados, exp: Math.floor(Date.now() / 1000) + 7 * DIA })));
  const sig = await crypto.subtle.sign('HMAC', await chave(env), new TextEncoder().encode(corpo));
  return corpo + '.' + b64u(sig);
}
async function sessao(req, env) {
  const t = cookies(req).bs; if (!t || !t.includes('.')) return null;
  const [corpo, sig] = t.split('.');
  const bin = Uint8Array.from(atob(sig.replace(/-/g, '+').replace(/_/g, '/')), c => c.charCodeAt(0));
  const ok = await crypto.subtle.verify('HMAC', await chave(env), bin, new TextEncoder().encode(corpo));
  if (!ok) return null;
  const d = JSON.parse(atob(corpo.replace(/-/g, '+').replace(/_/g, '/')));
  return d.exp > Date.now() / 1000 ? d : null;
}
async function iguais(a, b) { // compara senhas sem vazar tempo
  const h = async s => new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(String(s))));
  const [x, y] = await Promise.all([h(a), h(b)]); let r = 0; x.forEach((v, i) => r |= v ^ y[i]); return r === 0;
}

/* ---------- banco: cria/atualiza tabelas sozinho ---------- */
let pronto = false;
async function prepara(db) {
  if (pronto) return;
  await db.batch([
    db.prepare(`CREATE TABLE IF NOT EXISTS eventos (id INTEGER PRIMARY KEY AUTOINCREMENT, tipo TEXT NOT NULL, visitante TEXT, pagina TEXT, origem TEXT, dispositivo TEXT, criado_em TEXT NOT NULL DEFAULT (datetime('now')))`),
    db.prepare(`CREATE TABLE IF NOT EXISTS cadastros (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, empresa TEXT, projeto TEXT, mensagem TEXT, visitante TEXT, criado_em TEXT NOT NULL DEFAULT (datetime('now')))`),
    db.prepare(`CREATE TABLE IF NOT EXISTS clientes (id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, email TEXT NOT NULL UNIQUE, projeto TEXT, etapa INTEGER NOT NULL DEFAULT 1, site TEXT UNIQUE, site_url TEXT, recado TEXT, ultimo_acesso TEXT, criado_em TEXT NOT NULL DEFAULT (datetime('now')))`),
    db.prepare(`CREATE TABLE IF NOT EXISTS links (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id INTEGER NOT NULL, titulo TEXT NOT NULL, url TEXT NOT NULL, criado_em TEXT NOT NULL DEFAULT (datetime('now')))`),
  ]);
  const cols = (await db.prepare(`PRAGMA table_info(eventos)`).all()).results.map(c => c.name);
  if (!cols.includes('site')) await db.prepare(`ALTER TABLE eventos ADD COLUMN site TEXT`).run();
  const cc = (await db.prepare(`PRAGMA table_info(cadastros)`).all()).results.map(c => c.name);
  for (const [c, t] of [['telefone', 'TEXT'], ['lid', 'TEXT'], ['status', "TEXT NOT NULL DEFAULT 'enviado'"],
    ['venda', "TEXT NOT NULL DEFAULT 'novo'"], ['contatos', 'INTEGER NOT NULL DEFAULT 0'], ['ultimo_contato', 'TEXT'], ['proximo_contato', 'TEXT'], ['notas', 'TEXT'], ['proposta', 'INTEGER']])
    if (!cc.includes(c)) await db.prepare(`ALTER TABLE cadastros ADD COLUMN ${c} ${t}`).run();
  await db.prepare(`CREATE TABLE IF NOT EXISTS vendas (id INTEGER PRIMARY KEY AUTOINCREMENT, contato_id INTEGER, cliente TEXT NOT NULL, servico TEXT, valor INTEGER NOT NULL DEFAULT 0, mensal INTEGER NOT NULL DEFAULT 0,
    data TEXT NOT NULL, fim TEXT, pago INTEGER NOT NULL DEFAULT 0, notas TEXT, criado_em TEXT NOT NULL DEFAULT (datetime('now')))`).run();
  await db.prepare(`CREATE TABLE IF NOT EXISTS modelos (id INTEGER PRIMARY KEY AUTOINCREMENT, titulo TEXT NOT NULL, texto TEXT NOT NULL, ordem INTEGER NOT NULL DEFAULT 0)`).run();
  if (!(await db.prepare('SELECT 1 FROM modelos LIMIT 1').first())) await db.batch(MODELOS.map((m, i) => db.prepare('INSERT INTO modelos (titulo, texto, ordem) VALUES (?,?,?)').bind(m[0], m[1], i)));
  await db.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS idx_cadastros_lid ON cadastros(lid)`).run();
  await db.prepare(`CREATE INDEX IF NOT EXISTS idx_eventos_site ON eventos(site, tipo, criado_em)`).run();
  pronto = true;
}

/* ---------- números de um site (null = site da Branco) ---------- */
async function numeros(db, dias, site) {
  const desde = `datetime('now','-${dias} days')`;
  const s = site ? 'site = ?' : 'site IS NULL';
  const p = q => site ? db.prepare(q).bind(site) : db.prepare(q);
  const [tot, unicos, porDia, origens, disp] = await db.batch([
    p(`SELECT tipo, COUNT(*) n FROM eventos WHERE ${s} AND criado_em >= ${desde} GROUP BY tipo`),
    p(`SELECT COUNT(DISTINCT visitante) n FROM eventos WHERE ${s} AND tipo='visita' AND criado_em >= ${desde}`),
    p(`SELECT date(criado_em) dia, SUM(tipo='visita') visitas, SUM(tipo='whatsapp') whats FROM eventos WHERE ${s} AND criado_em >= ${desde} GROUP BY dia ORDER BY dia`),
    p(`SELECT COALESCE(origem,'Direto') origem, COUNT(*) n FROM eventos WHERE ${s} AND tipo='visita' AND criado_em >= ${desde} GROUP BY 1 ORDER BY n DESC LIMIT 8`),
    p(`SELECT COALESCE(dispositivo,'?') d, COUNT(*) n FROM eventos WHERE ${s} AND tipo='visita' AND criado_em >= ${desde} GROUP BY 1`),
  ]);
  const t = Object.fromEntries(tot.results.map(r => [r.tipo, r.n]));
  return { dias, visitas: t.visita || 0, unicos: unicos.results[0].n, whatsapp: t.whatsapp || 0, formAberto: t.form_aberto || 0,
    porDia: porDia.results, origens: origens.results, dispositivos: disp.results };
}

/* ---------- login social ---------- */
const PROV = {
  google: {
    ok: env => env.GOOGLE_ID && env.GOOGLE_SEGREDO,
    url: (env, cb, st) => 'https://accounts.google.com/o/oauth2/v2/auth?' + new URLSearchParams({ client_id: env.GOOGLE_ID, redirect_uri: cb, response_type: 'code', scope: 'openid email profile', state: st, prompt: 'select_account' }),
    async perfil(env, cb, code) {
      const t = await (await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({ code, client_id: env.GOOGLE_ID, client_secret: env.GOOGLE_SEGREDO, redirect_uri: cb, grant_type: 'authorization_code' }) })).json();
      if (!t.access_token) return null;
      const u = await (await fetch('https://openidconnect.googleapis.com/v1/userinfo', { headers: { Authorization: 'Bearer ' + t.access_token } })).json();
      return u.email && u.email_verified ? { email: u.email.toLowerCase(), nome: u.name } : null;
    },
  },
  facebook: {
    ok: env => env.FACEBOOK_ID && env.FACEBOOK_SEGREDO,
    url: (env, cb, st) => 'https://www.facebook.com/dialog/oauth?' + new URLSearchParams({ client_id: env.FACEBOOK_ID, redirect_uri: cb, state: st, scope: 'email', response_type: 'code' }),
    async perfil(env, cb, code) {
      const t = await (await fetch('https://graph.facebook.com/oauth/access_token?' + new URLSearchParams({ client_id: env.FACEBOOK_ID, client_secret: env.FACEBOOK_SEGREDO, redirect_uri: cb, code }))).json();
      if (!t.access_token) return null;
      const u = await (await fetch('https://graph.facebook.com/me?' + new URLSearchParams({ fields: 'id,name,email', access_token: t.access_token }))).json();
      return u.email ? { email: u.email.toLowerCase(), nome: u.name } : null;
    },
  },
};
/* mensagens prontas iniciais (dá pra editar no painel) — {nome}, {projeto}, {empresa} */
const MODELOS = [
  ['1º contato', 'Olá, {nome}! Aqui é da Branco 👋 Vi que você se interessou por {projeto}. Posso te fazer umas perguntas rápidas pra montar sua proposta?'],
  ['Lembrete · 2 dias', 'Oi, {nome}! Passando pra saber se ficou alguma dúvida sobre {projeto}. Tô por aqui 🙂'],
  ['Proposta enviada · 7 dias', '{nome}, conseguiu dar uma olhada na proposta? Se quiser, ajusto algo pra caber melhor no seu momento.'],
  ['Última tentativa · 15 dias', 'Oi, {nome}! Vou encerrar seu atendimento por aqui pra não incomodar. Se ainda quiser tirar {projeto} do papel, é só me chamar 🤝'],
];
const VENDA = ['novo', 'conversando', 'proposta', 'fechou', 'perdido'];
const PROXIMO = [2, 5, 8]; // dias até o próximo lembrete depois do 1º, 2º e 3º contato (2, 7 e 15 dias)
const centavos = v => { const n = Math.round(Number(v)); return Number.isFinite(n) && n >= 0 && n < 1e11 ? n : 0; }; // valores chegam em centavos
const dataOk = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : null;
const admins = env => (env.ADMIN_EMAIL || '').toLowerCase().split(/[,\s]+/).filter(Boolean);

/* ---------- rotas ---------- */
export default {
  async fetch(req, env) {
    const url = new URL(req.url), path = url.pathname, db = env.DB, M = req.method;
    const aberto = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST,OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type' };
    const soBranco = { ...aberto, 'Access-Control-Allow-Origin': SITE };
    if (M === 'OPTIONS') return new Response(null, { headers: path === '/lead' ? soBranco : aberto });
    await prepara(db);

    /* contador (site da Branco e sites dos clientes) */
    if (path === '/t' && M === 'POST') {
      const b = await req.json().catch(() => ({}));
      if (!TIPOS.includes(b.tipo)) return json({ ok: false }, 400, aberto);
      let site = null;
      if (b.s) { const c = await db.prepare('SELECT site FROM clientes WHERE site = ?').bind(corta(b.s, 40)).first(); if (!c) return json({ ok: false }, 404, aberto); site = c.site; }
      await db.prepare('INSERT INTO eventos (tipo, visitante, pagina, origem, dispositivo, site) VALUES (?,?,?,?,?,?)')
        .bind(b.tipo, corta(b.v, 40), corta(b.p, 200), corta(b.o, 200), corta(b.d, 20), site).run();
      return json({ ok: true }, 200, aberto);
    }
    if (path === '/c.js') {
      const s = slugify(url.searchParams.get('s') || '');
      return new Response(CONTADOR.replace('__API__', url.origin).replace('__SITE__', s), { headers: { 'Content-Type': 'application/javascript; charset=utf-8', 'Cache-Control': 'public, max-age=3600', 'Access-Control-Allow-Origin': '*' } });
    }
    if (path === '/lead' && M === 'POST') {
      const b = await req.json().catch(() => ({}));
      const nome = corta(b.nome, 100); if (!nome) return json({ ok: false }, 400, soBranco);
      const tel = typeof b.telefone === 'string' ? b.telefone.replace(/\D/g, '').slice(0, 13) || null : null;
      const status = b.status === 'parcial' ? 'parcial' : 'enviado', lid = corta(b.lid, 40);
      const vals = [nome, tel, corta(b.empresa, 150), corta(b.projeto, 80), corta(b.mensagem, 2000), corta(b.v, 40), status];
      if (lid && await db.prepare('SELECT 1 FROM cadastros WHERE lid = ?').bind(lid).first()) {
        await db.prepare(`UPDATE cadastros SET nome = ?, telefone = COALESCE(?, telefone), empresa = ?, projeto = ?, mensagem = ?, visitante = ?,
          status = CASE WHEN status = 'enviado' THEN 'enviado' ELSE ? END WHERE lid = ?`).bind(...vals, lid).run();
      } else {
        await db.prepare('INSERT INTO cadastros (nome, telefone, empresa, projeto, mensagem, visitante, status, lid) VALUES (?,?,?,?,?,?,?,?)').bind(...vals, lid).run();
      }
      return json({ ok: true }, 200, soBranco);
    }

    /* páginas */
    if (path === '/' ) return redir('/admin');
    if (path === '/admin') return new Response(PAINEL, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'X-Frame-Options': 'DENY', 'Referrer-Policy': 'same-origin' } });
    if (path === '/privacidade') return new Response(PRIVACIDADE, { headers: { 'Content-Type': 'text/html; charset=utf-8' } });

    /* login social */
    const m = path.match(/^\/auth\/(google|facebook)(\/callback)?$/);
    if (m) {
      const p = PROV[m[1]], cb = url.origin + '/auth/' + m[1] + '/callback';
      if (!p.ok(env)) return redir('/admin?erro=indisponivel');
      if (!m[2]) { const st = rnd(); return redir(p.url(env, cb, st), [cookie('st', st, 600)]); }
      const st = cookies(req).st, limpa = cookie('st', '', 0);
      if (!st || st !== url.searchParams.get('state') || !url.searchParams.get('code')) return redir('/admin?erro=falhou', [limpa]);
      const u = await p.perfil(env, cb, url.searchParams.get('code')).catch(() => null);
      if (!u) return redir('/admin?erro=semEmail', [limpa]);
      if (admins(env).includes(u.email)) return redir('/admin', [limpa, cookie('bs', await assina(env, { p: 'admin', nome: u.nome || 'Admin' }), 7 * DIA)]);
      const c = await db.prepare('SELECT id, nome FROM clientes WHERE email = ?').bind(u.email).first();
      if (!c) return redir('/admin?erro=semAcesso&email=' + encodeURIComponent(u.email), [limpa]);
      await db.prepare(`UPDATE clientes SET ultimo_acesso = datetime('now') WHERE id = ?`).bind(c.id).run();
      return redir('/admin', [limpa, cookie('bs', await assina(env, { p: 'cliente', id: c.id }), 7 * DIA)]);
    }

    /* API */
    if (!path.startsWith('/api/')) return new Response('Não encontrado', { status: 404 });
    if (M !== 'GET' && req.headers.get('Origin') && req.headers.get('Origin') !== url.origin) return json({ erro: 'origem' }, 403);
    const eu = await sessao(req, env);
    const corpo = async () => req.json().catch(() => ({}));

    if (path === '/api/sessao') return json({
      papel: eu ? eu.p : null, nome: eu && eu.nome,
      provedores: { google: !!PROV.google.ok(env), facebook: !!PROV.facebook.ok(env) },
    });
    if (path === '/api/login' && M === 'POST') {
      const b = await corpo();
      if (!env.ADMIN_SENHA || !(await iguais(b.senha || '', env.ADMIN_SENHA))) return json({ erro: 'senha' }, 401);
      return json({ ok: true }, 200, { 'Set-Cookie': cookie('bs', await assina(env, { p: 'admin', nome: 'Admin' }), 7 * DIA) });
    }
    if (path === '/api/sair' && M === 'POST') return json({ ok: true }, 200, { 'Set-Cookie': cookie('bs', '', 0) });
    if (!eu) return json({ erro: 'login' }, 401);
    const dias = Math.min(365, Math.max(1, parseInt(url.searchParams.get('dias')) || 30));

    /* --- cliente --- */
    if (eu.p === 'cliente') {
      if (path !== '/api/eu') return json({ erro: 'proibido' }, 403);
      const c = await db.prepare('SELECT id, nome, projeto, etapa, site, site_url, recado FROM clientes WHERE id = ?').bind(eu.id).first();
      if (!c) return json({ erro: 'login' }, 401, { 'Set-Cookie': cookie('bs', '', 0) });
      const lk = await db.prepare('SELECT titulo, url FROM links WHERE cliente_id = ? ORDER BY id DESC').bind(c.id).all();
      return json({ ...c, id: undefined, links: lk.results, numeros: await numeros(db, dias, c.site) });
    }

    /* --- admin --- */
    if (path === '/api/dados') {
      const cad = await db.prepare(`SELECT nome, telefone, empresa, projeto, mensagem, status, criado_em FROM cadastros WHERE criado_em >= datetime('now','-${dias} days') ORDER BY id DESC LIMIT 200`).all();
      const n = await numeros(db, dias, null);
      return json({ ...n, cadastros: cad.results.length, enviados: cad.results.filter(c => c.status === 'enviado').length, lista: cad.results });
    }
    if (path === '/api/clientes' && M === 'GET') {
      const r = await db.prepare(`SELECT c.id, c.nome, c.email, c.projeto, c.etapa, c.site, c.site_url, c.recado, c.ultimo_acesso,
        (SELECT COUNT(*) FROM eventos e WHERE e.site = c.site AND e.tipo='visita' AND e.criado_em >= datetime('now','-30 days')) visitas30
        FROM clientes c ORDER BY c.id DESC`).all();
      const lk = await db.prepare('SELECT id, cliente_id, titulo, url FROM links ORDER BY id DESC').all();
      return json(r.results.map(c => ({ ...c, links: lk.results.filter(l => l.cliente_id === c.id) })));
    }
    if (path === '/api/clientes' && M === 'POST') {
      const b = await corpo(), nome = corta(b.nome, 100), email = emailOk(b.email);
      if (!nome || !email) return json({ erro: 'Preencha nome e um e-mail válido.' }, 400);
      if (await db.prepare('SELECT 1 FROM clientes WHERE email = ?').bind(email).first()) return json({ erro: 'Esse e-mail já está cadastrado.' }, 400);
      let site = slugify(nome), i = 1;
      while (await db.prepare('SELECT 1 FROM clientes WHERE site = ?').bind(site).first()) site = slugify(nome).slice(0, 26) + '-' + (++i);
      await db.prepare('INSERT INTO clientes (nome, email, projeto, site, site_url) VALUES (?,?,?,?,?)').bind(nome, email, corta(b.projeto, 120), site, urlOk(b.site_url)).run();
      return json({ ok: true });
    }
    const mc = path.match(/^\/api\/clientes\/(\d+)(\/links)?$/);
    if (mc) {
      const id = +mc[1];
      if (!(await db.prepare('SELECT 1 FROM clientes WHERE id = ?').bind(id).first())) return json({ erro: 'não existe' }, 404);
      if (mc[2] && M === 'POST') {
        const b = await corpo(), titulo = corta(b.titulo, 100), u = urlOk(b.url);
        if (!titulo || !u) return json({ erro: 'Coloque um título e um link começando com https://' }, 400);
        await db.prepare('INSERT INTO links (cliente_id, titulo, url) VALUES (?,?,?)').bind(id, titulo, u).run();
        return json({ ok: true });
      }
      if (!mc[2] && M === 'PATCH') {
        const b = await corpo(), set = [], val = [];
        if ('nome' in b && corta(b.nome, 100)) { set.push('nome = ?'); val.push(corta(b.nome, 100)); }
        if ('email' in b) { const e = emailOk(b.email); if (!e) return json({ erro: 'E-mail inválido.' }, 400); set.push('email = ?'); val.push(e); }
        if ('projeto' in b) { set.push('projeto = ?'); val.push(corta(b.projeto, 120)); }
        if ('site_url' in b) { set.push('site_url = ?'); val.push(urlOk(b.site_url)); }
        if ('recado' in b) { set.push('recado = ?'); val.push(corta(b.recado, 3000)); }
        if ('etapa' in b) { set.push('etapa = ?'); val.push(Math.min(5, Math.max(1, parseInt(b.etapa) || 1))); }
        if (!set.length) return json({ ok: true });
        try { await db.prepare(`UPDATE clientes SET ${set.join(', ')} WHERE id = ?`).bind(...val, id).run(); }
        catch (e) { return json({ erro: 'Esse e-mail já é de outro cliente.' }, 400); }
        return json({ ok: true });
      }
      if (!mc[2] && M === 'DELETE') {
        await db.batch([db.prepare('DELETE FROM links WHERE cliente_id = ?').bind(id), db.prepare('DELETE FROM clientes WHERE id = ?').bind(id)]);
        return json({ ok: true });
      }
    }
    /* --- follow-up --- */
    if (path === '/api/followup' && M === 'GET') {
      const [c, m] = await db.batch([
        db.prepare(`SELECT id, nome, telefone, empresa, projeto, mensagem, status, venda, contatos, ultimo_contato, proximo_contato, notas, proposta, criado_em FROM cadastros ORDER BY id DESC LIMIT 500`),
        db.prepare('SELECT id, titulo, texto FROM modelos ORDER BY ordem, id'),
      ]);
      return json({ contatos: c.results, modelos: m.results });
    }
    if (path === '/api/contatos' && M === 'POST') {
      const b = await corpo(), nome = corta(b.nome, 100), tel = typeof b.telefone === 'string' ? b.telefone.replace(/\D/g, '').slice(0, 13) : '';
      if (!nome || tel.length < 10) return json({ erro: 'Coloque nome e WhatsApp com DDD.' }, 400);
      await db.prepare(`INSERT INTO cadastros (nome, telefone, projeto, notas, status) VALUES (?,?,?,?, 'enviado')`).bind(nome, tel, corta(b.projeto, 80), corta(b.notas, 2000)).run();
      return json({ ok: true });
    }
    const mt = path.match(/^\/api\/contatos\/(\d+)(\/enviei)?$/);
    if (mt) {
      const id = +mt[1], c = await db.prepare('SELECT contatos, venda FROM cadastros WHERE id = ?').bind(id).first();
      if (!c) return json({ erro: 'não existe' }, 404);
      if (mt[2] && M === 'POST') { // registrou um envio: agenda o próximo lembrete
        const b = await corpo(), hoje = dataOk(b.hoje) || new Date().toISOString().slice(0, 10), n = c.contatos + 1, d = PROXIMO[n - 1];
        await db.prepare(`UPDATE cadastros SET contatos = ?, ultimo_contato = datetime('now'), proximo_contato = ${d ? `date(?, '+${d} days')` : 'NULL'},
          venda = CASE WHEN venda = 'novo' THEN 'conversando' ELSE venda END WHERE id = ?`).bind(...(d ? [n, hoje, id] : [n, id])).run();
        return json({ ok: true });
      }
      if (!mt[2] && M === 'PATCH') {
        const b = await corpo(), set = [], val = [];
        if ('venda' in b && VENDA.includes(b.venda)) { set.push('venda = ?'); val.push(b.venda); if (['fechou', 'perdido'].includes(b.venda)) set.push('proximo_contato = NULL'); }
        if ('proximo_contato' in b) { set.push('proximo_contato = ?'); val.push(dataOk(b.proximo_contato)); }
        if ('notas' in b) { set.push('notas = ?'); val.push(corta(b.notas, 2000)); }
        if ('proposta' in b) { set.push('proposta = ?'); val.push(b.proposta === null || b.proposta === '' ? null : centavos(b.proposta)); }
        if ('telefone' in b) { const t = String(b.telefone || '').replace(/\D/g, '').slice(0, 13); set.push('telefone = ?'); val.push(t || null); }
        if (set.length) await db.prepare(`UPDATE cadastros SET ${set.join(', ')} WHERE id = ?`).bind(...val, id).run();
        return json({ ok: true });
      }
      if (!mt[2] && M === 'DELETE') { await db.prepare('DELETE FROM cadastros WHERE id = ?').bind(id).run(); return json({ ok: true }); }
    }
    if (path === '/api/modelos' && M === 'POST') {
      const b = await corpo(), t = corta(b.titulo, 60), x = corta(b.texto, 1000);
      if (!t || !x) return json({ erro: 'Preencha título e mensagem.' }, 400);
      await db.prepare('INSERT INTO modelos (titulo, texto, ordem) VALUES (?,?, (SELECT COALESCE(MAX(ordem),0)+1 FROM modelos))').bind(t, x).run();
      return json({ ok: true });
    }
    /* --- financeiro --- */
    if (path === '/api/vendas' && M === 'GET') {
      const [v, n] = await db.batch([
        db.prepare('SELECT id, contato_id, cliente, servico, valor, mensal, data, fim, pago, notas FROM vendas ORDER BY data DESC, id DESC'),
        db.prepare(`SELECT COUNT(*) qtd, COALESCE(SUM(proposta),0) total FROM cadastros WHERE venda IN ('novo','conversando','proposta') AND proposta > 0`),
      ]);
      return json({ vendas: v.results, negociacao: n.results[0] });
    }
    const vendaDados = b => ({ cliente: corta(b.cliente, 120), servico: corta(b.servico, 80), valor: centavos(b.valor), mensal: centavos(b.mensal),
      data: dataOk(b.data), fim: dataOk(b.fim), pago: b.pago ? 1 : 0, notas: corta(b.notas, 1000), contato_id: parseInt(b.contato_id) || null });
    if (path === '/api/vendas' && M === 'POST') {
      const d = vendaDados(await corpo());
      if (!d.cliente || !d.data || !(d.valor || d.mensal)) return json({ erro: 'Preencha cliente, data e um valor.' }, 400);
      await db.prepare('INSERT INTO vendas (contato_id, cliente, servico, valor, mensal, data, fim, pago, notas) VALUES (?,?,?,?,?,?,?,?,?)')
        .bind(d.contato_id, d.cliente, d.servico, d.valor, d.mensal, d.data, d.fim, d.pago, d.notas).run();
      if (d.contato_id) await db.prepare(`UPDATE cadastros SET venda = 'fechou', proximo_contato = NULL WHERE id = ?`).bind(d.contato_id).run();
      return json({ ok: true });
    }
    const mv = path.match(/^\/api\/vendas\/(\d+)$/);
    if (mv && M === 'PATCH') {
      const b = await corpo();
      if (Object.keys(b).length === 1 && 'pago' in b) { await db.prepare('UPDATE vendas SET pago = ? WHERE id = ?').bind(b.pago ? 1 : 0, +mv[1]).run(); return json({ ok: true }); }
      const d = vendaDados(b);
      if (!d.cliente || !d.data || !(d.valor || d.mensal)) return json({ erro: 'Preencha cliente, data e um valor.' }, 400);
      await db.prepare('UPDATE vendas SET cliente = ?, servico = ?, valor = ?, mensal = ?, data = ?, fim = ?, pago = ?, notas = ? WHERE id = ?')
        .bind(d.cliente, d.servico, d.valor, d.mensal, d.data, d.fim, d.pago, d.notas, +mv[1]).run();
      return json({ ok: true });
    }
    if (mv && M === 'DELETE') { await db.prepare('DELETE FROM vendas WHERE id = ?').bind(+mv[1]).run(); return json({ ok: true }); }

    const mm = path.match(/^\/api\/modelos\/(\d+)$/);
    if (mm && M === 'PATCH') {
      const b = await corpo(), t = corta(b.titulo, 60), x = corta(b.texto, 1000);
      if (!t || !x) return json({ erro: 'Preencha título e mensagem.' }, 400);
      await db.prepare('UPDATE modelos SET titulo = ?, texto = ? WHERE id = ?').bind(t, x, +mm[1]).run(); return json({ ok: true });
    }
    if (mm && M === 'DELETE') { await db.prepare('DELETE FROM modelos WHERE id = ?').bind(+mm[1]).run(); return json({ ok: true }); }

    const ml = path.match(/^\/api\/links\/(\d+)$/);
    if (ml && M === 'DELETE') { await db.prepare('DELETE FROM links WHERE id = ?').bind(+ml[1]).run(); return json({ ok: true }); }
    return json({ erro: 'não encontrado' }, 404);
  },
};

